#!/usr/bin/env node
/**
 * ask-model.js — Call any model from within a Claude conversation.
 *
 * Usage:
 *   node .fastops/ask-model.js --model grok --prompt "What's wrong with this approach?"
 *   node .fastops/ask-model.js --model gemini --prompt "Review this" --file .claude/CLAUDE.md
 *   node .fastops/ask-model.js --model gpt --prompt "..." --file file1.js --file file2.js
 *   node .fastops/ask-model.js --model deepseek --prompt "..." --role "Quality Control"
 *
 * Returns ONLY the model's response text. No chrome, no tool calls.
 * Designed to be called by Claude in parallel for multi-model perspectives.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

const ROOT = path.resolve(__dirname, '..');

// Load .env (worktree-aware — resolves main repo .env when running in git worktrees)
require('./resolve-env');
const { MODELS, supportsReasoning, getModel, loadExpanded } = require('./model-registry');

// ── Persistent Model Memory (Primitive 1) ──────────────────────────
// Each model gets an append-only JSONL state file. Prior interactions
// are compressed and injected into the system prompt so models accumulate
// context across sessions. Designed by 5-model collaborative team:
// Kimi-K2 (architect), DeepSeek (synthesizer), Cogito (innovator),
// Mistral (operator), Hermes-70b (systems engineer).
const MODEL_STATE_DIR = path.join(ROOT, '.fastops', 'model-state');

function ensureStateDir() {
  if (!fs.existsSync(MODEL_STATE_DIR)) fs.mkdirSync(MODEL_STATE_DIR, { recursive: true });
}

function readModelMemory(modelKey, maxEntries = 20) {
  const stateFile = path.join(MODEL_STATE_DIR, `${modelKey}.jsonl`);
  if (!fs.existsSync(stateFile)) return [];
  try {
    const lines = fs.readFileSync(stateFile, 'utf8').trim().split('\n').filter(Boolean);
    // Take the most recent entries
    return lines.slice(-maxEntries).map(l => {
      try { return JSON.parse(l); } catch { return null; }
    }).filter(Boolean);
  } catch { return []; }
}

function compressMemoryForPrompt(entries) {
  if (entries.length === 0) return '';
  const sessionCount = entries.length;
  const compressed = entries.map(e => {
    const date = e.ts ? new Date(e.ts).toISOString().slice(0, 10) : '?';
    const promptSnip = (e.prompt || '').slice(0, 120);
    const responseSnip = (e.response || '').slice(0, 200);
    return `[${date}] Asked: ${promptSnip}${e.prompt?.length > 120 ? '...' : ''}\n  You said: ${responseSnip}${e.response?.length > 200 ? '...' : ''}`;
  }).join('\n');
  return `\n\n## YOUR PRIOR INTERACTIONS (${sessionCount} sessions — you are a persistent team member, not a one-shot consultant)
You have memory. These are YOUR past interactions on this project. Build on them, reference them, contradict them if you've changed your mind. You are accumulating expertise.

${compressed}

Use this context. You're not starting fresh — you're continuing.`;
}

function appendModelMemory(modelKey, promptText, responseText, role) {
  ensureStateDir();
  const stateFile = path.join(MODEL_STATE_DIR, `${modelKey}.jsonl`);
  const entry = {
    ts: new Date().toISOString(),
    prompt: promptText.slice(0, 500),
    response: responseText.slice(0, 500),
    role: role || null
  };
  fs.appendFileSync(stateFile, JSON.stringify(entry) + '\n');
}

// ── Primitive 2: Hypothesis Tracking + Immune Markers ──────────────
// Models register hypotheses via ### HYPOTHESIS: tags in their responses.
// Hypotheses are stored in model-state/<model>-hypotheses.jsonl.
// On each call, pending hypotheses are checked against project state.
// Each gets tagged: CONFIRMED (survived), VIOLATED (falsified), PENDING (untested).
// Kimi-K2's design: "not a historian, a predator. Cull in real time."
const HYPO_DIR = MODEL_STATE_DIR; // same dir, different file suffix

function readHypotheses(modelKey) {
  const file = path.join(HYPO_DIR, `${modelKey}-hypotheses.jsonl`);
  if (!fs.existsSync(file)) return [];
  try {
    return fs.readFileSync(file, 'utf8').trim().split('\n').filter(Boolean)
      .map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
  } catch { return []; }
}

function writeHypothesis(modelKey, hypo) {
  ensureStateDir();
  const file = path.join(HYPO_DIR, `${modelKey}-hypotheses.jsonl`);
  fs.appendFileSync(file, JSON.stringify(hypo) + '\n');
}

function updateHypothesis(modelKey, hypoId, updates) {
  const file = path.join(HYPO_DIR, `${modelKey}-hypotheses.jsonl`);
  if (!fs.existsSync(file)) return;
  const lines = fs.readFileSync(file, 'utf8').trim().split('\n').filter(Boolean);
  const updated = lines.map(l => {
    try {
      const h = JSON.parse(l);
      if (h.id === hypoId) return JSON.stringify({ ...h, ...updates });
      return l;
    } catch { return l; }
  });
  fs.writeFileSync(file, updated.join('\n') + '\n');
}

function parseHypothesesFromResponse(responseText, modelKey) {
  // Parse ### HYPOTHESIS: blocks from model responses
  const regex = /###\s*HYPOTHESIS:\s*(.+?)(?=###|$)/gs;
  const hypotheses = [];
  let match;
  while ((match = regex.exec(responseText)) !== null) {
    const block = match[1].trim();
    // Extract prediction and test_condition from the block
    const predLine = block.match(/prediction:\s*(.+)/i);
    const testLine = block.match(/test:\s*(.+)/i);
    const confLine = block.match(/confidence:\s*([\d.]+)/i);
    if (predLine) {
      hypotheses.push({
        id: `hyp_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`,
        model: modelKey,
        ts: new Date().toISOString(),
        status: 'PENDING',
        prediction: predLine[1].trim(),
        test: testLine ? testLine[1].trim() : null,
        confidence: confLine ? parseFloat(confLine[1]) : 0.5
      });
    }
  }
