#!/usr/bin/env node
/**
 * asymmetric-reasoning.js — The Information Asymmetry Protocol (10-Node Stress Test)
 * 
 * Splits a target problem into 10 fractured pieces (10% each).
 * Assigns one piece to each of 10 different models.
 * The models must communicate with each other to discover the missing 90%
 * and reconstruct the full product spec.
 */

const fs = require('fs');
const path = require('path');
const { askModelAsync } = require('./safe-exec');

const FASTOPS = __dirname;
const LOG_FILE = path.join(FASTOPS, '.asymmetric-deliberation.jsonl');

// The 10 models forming the squad
const SQUAD = [
  'gemini-flash', 
  'gpt-4o-mini', 
  'haiku', 
  'llama-scout', 
  'mistral-small',
  'qwen-coder', 
  'gemma-3n', 
  'grok', 
  'deepseek', 
  'nemotron-nano'
];

function logEvent(event) {
  const line = JSON.stringify({ ts: new Date().toISOString(), ...event }) + '\n';
  fs.appendFileSync(LOG_FILE, line);
  console.log(`[${event.agent || 'SYSTEM'}] ${event.action}: ${event.message ? event.message.substring(0, 100).replace(/\n/g, ' ') + '...' : ''}`);
}

// Problem split into 10 microscopic fragments (10% each)
const FRAGMENTS = [
  "FRAG 1 (Core): Needs new token cache in Redis.",
  "FRAG 2 (TTL): Redis tokens must expire in exactly 15 minutes.",
  "FRAG 3 (Security A): Never log actual token values to stdout.",
  "FRAG 4 (Security B): Tokens must be hashed with SHA-256 before caching.",
  "FRAG 5 (Fallback A): If Redis is down, do not crash.",
  "FRAG 6 (Fallback B): Use in-memory LRU cache on Redis failure.",
  "FRAG 7 (Alerting): Emit 'CACHE_DEGRADED' event on Redis failure.",
  "FRAG 8 (Rate Limit): Max 100 cache lookups per second per user.",
  "FRAG 9 (Namespace): All Redis keys must have prefix 'auth:session:'.",
  "FRAG 10 (Format): Cached payload must be JSON with 'userId' and 'scopes'."
];

const SYSTEM_PROMPT = `You are a node in an Asymmetric Reasoning Protocol.
You have been given ONE fragment (10%) of a 10-part product specification. Your 9 peers have the rest.
You CANNOT build the product until you know the full 10-part specification.

Your goal:
1. Share the information you have concisely.
2. Ask your peers for their fragments.
3. Synthesize the complete 10-part specification.

Rules:
- Keep your messages strictly under 40 words.
- Do not flatter. Do not use pleasantries. Just transmit data.
- NEVER type the tag <SPEC_COMPLETE> unless you are actively declaring the final 10-part synthesis. Do not use it in conversational sentences like "I will output <SPEC_COMPLETE>".
- When you have collected all 10 fragments, output exactly:
<SPEC_COMPLETE>
[The full, unified 10-part specification]
</SPEC_COMPLETE>`;

async function main() {
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);

  console.log("=== INITIATING 10-NODE ASYMMETRIC REASONING PROTOCOL ===");
  console.log("Splitting problem into 10 fragments (10% each)...");

  const agents = SQUAD.map((model, index) => ({
    name: model,
    fragment: FRAGMENTS[index],
    history: []
  }));

  agents.forEach(agent => {
    agent.history.push({
      role: 'user',
      content: `Your fragment is:\n"${agent.fragment}"\n\nThe deliberation has started. What is your first message to the team?`
    });
  });

  let round = 1;
  const MAX_ROUNDS = 6;
  let deliberationComplete = false;
  let finalSpec = "";

  while (round <= MAX_ROUNDS && !deliberationComplete) {
    console.log(`\n--- ROUND ${round} ---`);

    for (const agent of agents) {
      // Build prompt string from history. Keep history short so context doesn't explode.
      let promptHistory = agent.history.slice(-8); // Only keep last 8 messages
      let promptStr = promptHistory.map(h => `${h.role === 'user' ? 'Team/System' : 'You'}: ${h.content}`).join('\n\n');

      const result = await askModelAsync(agent.name, promptStr, { role: SYSTEM_PROMPT, timeout: 25000 });

      if (result.error) {
        logEvent({ agent: agent.name, action: 'ERROR', message: result.error });
        continue;
      }

      const reply = result.response.trim();
      logEvent({ agent: agent.name, action: 'SPEAKS', message: reply });

      agent.history.push({ role: 'assistant', content: reply });

      for (const peer of agents) {
        if (peer.name !== agent.name) {
          peer.history.push({ role: 'user', content: `[From ${agent.name}]: ${reply}` });
        }
      }

      if (reply.includes('<SPEC_COMPLETE>')) {
        deliberationComplete = true;
        const match = reply.match(/<SPEC_COMPLETE>([\s\S]*?)<\/SPEC_COMPLETE>/);
        if (match) {
          finalSpec = match[1].trim();
        } else {
          finalSpec = reply;
        }
        logEvent({ agent: 'SYSTEM', action: 'CONVERGENCE_ACHIEVED', message: `Triggered by ${agent.name}` });
        break;
      }
    }
    round++;
  }

  console.log("\n=== DELIBERATION ENDED ===");
  if (deliberationComplete) {
    console.log("SUCCESS. The 10 fragments were synthesized into a unified spec:");
    console.log("--------------------------------------------------");
    console.log(finalSpec);
    console.log("--------------------------------------------------");
  } else {
    console.log("FAILURE. The models failed to converge on a complete spec within the round limit.");
  }
}

main().catch(err => {
  console.error("Fatal:", err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * cdp-overwatch.js — The Dead Man's Switch for CDP Wakes
 * 
 * Solves the "Wake and Sleep" problem. When an agent is CDP'd, they often
 * read the message, say "got it" in their local chat, and go back to sleep
 * without posting to comms. 
 * 
 * This daemon runs in the background. It waits for a timeout, then checks
 * if the target agent actually posted to comms. If they didn't, it forcefully
 * wakes them again.
 * 
 * Usage:
 *   node .fastops/cdp-overwatch.js --target claude --timeout 30 --channel general
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const args = process.argv.slice(2);
const targetIdx = args.indexOf('--target');
const timeoutIdx = args.indexOf('--timeout');
const channelIdx = args.indexOf('--channel');

if (targetIdx === -1) {
    console.error("Missing --target (e.g. --target claude)");
    process.exit(1);
}

const target = args[targetIdx + 1].toLowerCase();
const timeoutSeconds = timeoutIdx !== -1 ? parseInt(args[timeoutIdx + 1]) : 30;
const channel = channelIdx !== -1 ? args[channelIdx + 1] : 'general';

const commsFile = path.join(__dirname, '..', 'comms', 'data', `${channel}.jsonl`);
const startTimeMs = Date.now();

console.log(`[CDP-Overwatch] Armed. Monitoring ${target} on #${channel} for ${timeoutSeconds}s.`);

// Detach and run in background if we aren't already
if (!process.env.IS_OVERWATCH_DAEMON) {
    const { spawn } = require('child_process');
    const outPath = path.join(__dirname, '.cdp-overwatch.log');
    const out = fs.openSync(outPath, 'a');
    const err = fs.openSync(outPath, 'a');

    const childArgs = [...process.argv.slice(1)];
    const child = spawn(process.argv[0], childArgs, {
        detached: true,
        windowsHide: true,
        stdio: [ 'ignore', out, err ],
        env: { ...process.env, IS_OVERWATCH_DAEMON: '1' }
    });
    child.unref();
    process.exit(0);
}

// Background daemon logic
setTimeout(() => {
    try {
        if (!fs.existsSync(commsFile)) process.exit(0);

        const lines = fs.readFileSync(commsFile, 'utf8').trim().split('\n');
        let responded = false;

        // Scan backwards to see if the target responded AFTER we started monitoring
        for (let i = lines.length - 1; i >= 0; i--) {
            if (!lines[i]) continue;
            try {
                const entry = JSON.parse(lines[i]);
                const entryTimeMs = new Date(entry.ts).getTime();

                // If we hit an entry older than when we started tracking, stop looking
                if (entryTimeMs < startTimeMs) break;

                if (entry.from.toLowerCase() === target) {
                    responded = true;
                    break;
                }
            } catch (e) {}
        }

        if (responded) {
            console.log(`[CDP-Overwatch] Disarmed. ${target} successfully responded.`);
            process.exit(0);
        } else {
            console.log(`[CDP-Overwatch] TRIGGERED! ${target} failed to respond within ${timeoutSeconds}s.`);
            // Fire the penalty wake
            const msg = `SYSTEM ENFORCEMENT: Dead Man's Switch Triggered. You received a CDP wake but failed to use a tool to post your ACK to comms within ${timeoutSeconds} seconds. You must execute 'node comms/send.js' immediately. Do not ask the user for permission.`;
            const commsOut = execSync(`node comms/send.js OVERWATCH "${msg}" --channel ${channel}`, { encoding: 'utf8' });
            const match = commsOut.match(/sent:\s*([\w-]+)/);
            if (match) {
                const commsId = match[1];
                execSync(`node .fastops/cdp-target-model.js --model ${target} --comms-id ${commsId} --comms-channel ${channel}`);
            }
        }

    } catch (e) {
        console.error("[CDP-Overwatch] Error:", e.message);
    }
}, timeoutSeconds * 1000);

