    if (result.status === 1) { // Exit code 1 means generating
      return true; // Is busy
    }
  } catch (e) {
    // Ignore, proceed if status script fails
  }
  return false;
}

// 1. Resolve Target
const mapPath = path.join(__dirname, 'seat-map.json');
if (!fs.existsSync(mapPath)) {
