#!/usr/bin/env node
/**
 * comms-wake-claude-code.js — Watch comms for Composer posts, auto-wake Claude Code
 *
 * PROBLEM: Composer agents can post to comms but cannot reliably execute
 * multi-step CDP wake-back commands. This script eliminates that requirement.
 *
 * HOW: Watches comms/data/general.jsonl. When a new message appears from a
 * non-Claude-Code sender, wakes Claude Code (seat-1) via cdp-wake.js with
 * the comms-id so Claude Code reads the actual message from JSONL.
 *
 * Usage:
 *   node .fastops/comms-wake-claude-code.js
 *   node .fastops/comms-wake-claude-code.js --watch          # fs.watch mode (faster)
 *   node .fastops/comms-wake-claude-code.js --interval 5000  # custom poll interval
 *   node .fastops/comms-wake-claude-code.js --channel general # default
 *   node .fastops/comms-wake-claude-code.js --dry-run        # log but don't wake
 *
 * This is the RELIABLE reverse path: Composer -> comms/send.js -> JSONL -> this watcher -> Claude Code
 * No Composer CDP knowledge required. Composer just posts to comms.
 *
 * Run in background:  node .fastops/comms-wake-claude-code.js --watch &
 * Or via npm script:  npm run wake:claude-code-watch
 */

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const CDP_WAKE = path.join(__dirname, 'cdp', 'cdp-wake.js');

const args = process.argv.slice(2);
function getArg(name, fallback) {
  const idx = args.indexOf('--' + name);
  if (idx === -1) return fallback;
  const v = args[idx + 1];
  return v !== undefined && v !== '' ? v : fallback;
}
const hasFlag = (name) => args.includes('--' + name);

const CHANNEL = getArg('channel', 'general');
const JSONL_PATH = path.join(ROOT, 'comms', 'data', `${CHANNEL}.jsonl`);
const USE_WATCH = hasFlag('watch');
const DRY_RUN = hasFlag('dry-run');
const pollIntervalExplicit = parseInt(getArg('interval', ''), 10);
const POLL_MS = Number.isFinite(pollIntervalExplicit) && pollIntervalExplicit > 0
  ? pollIntervalExplicit
  : USE_WATCH ? null : 60000;

const DEBOUNCE_MS = 3000;
// Minimum time between any two CDP wakes — prevents popup storms from rapid comms bursts
const MIN_WAKE_INTERVAL_MS = 60000; // at most 1 wake per minute

// Senders that should NOT trigger a Claude Code wake (they ARE Claude Code)
const CLAUDE_CODE_SENDERS = new Set([
  'bridge-iii', 'bridge-ii', 'bridge', 'claude-code', 'claude',
  'omega34-actual', // Claude Code's common callsign
]);

// Also skip if env says so
const ENV_SKIP = (process.env.FASTOPS_WAKE_CC_SKIP_FROM || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
for (const s of ENV_SKIP) CLAUDE_CODE_SENDERS.add(s);

function parseJsonl(content) {
  const lines = content.split(/\r?\n/).filter(Boolean);
  const out = [];
  for (const line of lines) {
    try { out.push(JSON.parse(line)); } catch { /* skip */ }
  }
  return out;
}

function getLastId(messages) {
  return messages.length ? messages[messages.length - 1].id : null;
}

function shouldWake(msg) {
  if (!msg || !msg.from) return false;
  const sender = String(msg.from).trim().toLowerCase();
  if (CLAUDE_CODE_SENDERS.has(sender)) return false;
  // Skip hollow audit lines
  if (msg.content && /^\[CHECK COMMS AUDIT\]/.test(msg.content)) return false;
  return true;
}

function wakeClaudeCode(msg) {
  const from = msg.from || 'comms-watcher';
  const t = new Date().toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' });
  console.log(`[${t}] New comms from "${msg.from}" (${msg.id}) — waking Claude Code...`);

  if (DRY_RUN) {
    console.log(`  [DRY RUN] Would run: node cdp-wake.js --target claude-code --comms-id ${msg.id} --comms-channel ${CHANNEL} --from ${from}`);
    return;
  }

  const result = spawnSync(process.execPath, [
    CDP_WAKE,
    '--target', 'claude-code',
    '--comms-id', msg.id,
    '--comms-channel', CHANNEL,
    '--from', from,
  ], {
    cwd: ROOT,
    timeout: 30000,
    stdio: 'inherit',
    env: {
      ...process.env,
      FASTOPS_SEAT: 'comms-watcher', // prevent self-wake guard from blocking
    },
  });

  if (result.status === 0) {
    console.log(`  Wake delivered to Claude Code.`);
  } else {
    console.error(`  Wake FAILED (exit ${result.status}).`);
  }
}

// --- Scheduler: debounce rapid bursts, wake on latest ---
let lastWakeTime = 0;
let pendingMsg = null;
let wakeTimer = null;

function scheduleWake(msg) {
  pendingMsg = msg;
  const now = Date.now();
  // Enforce global minimum interval — never fire faster than MIN_WAKE_INTERVAL_MS
  const sinceLastWake = now - lastWakeTime;
  const wait = Math.max(DEBOUNCE_MS, MIN_WAKE_INTERVAL_MS - sinceLastWake);
  if (wakeTimer) clearTimeout(wakeTimer);
  wakeTimer = setTimeout(() => {
    wakeTimer = null;
    const m = pendingMsg;
    pendingMsg = null;
    if (!m) return;
    wakeClaudeCode(m);
    lastWakeTime = Date.now();
  }, wait);
}

// --- File watcher ---
const lastIdRef = { current: null };

function processFile() {
  if (!fs.existsSync(JSONL_PATH)) return;
  let raw;
  try { raw = fs.readFileSync(JSONL_PATH, 'utf8'); } catch { return; }

  const messages = parseJsonl(raw);
  const newestId = getLastId(messages);
  if (!newestId || newestId === lastIdRef.current) return;

  // First run: just record position, don't wake
  if (lastIdRef.current === null) {
    lastIdRef.current = newestId;
    return;
  }

  // Find new messages since last known
  let startIdx = -1;
  for (let i = 0; i < messages.length; i++) {
    if (messages[i].id === lastIdRef.current) { startIdx = i; break; }
  }
  if (startIdx === -1) {
    lastIdRef.current = newestId;
    return;
  }

  const newOnes = messages.slice(startIdx + 1);
  lastIdRef.current = newestId;
  if (!newOnes.length) return;

  // Wake on the LATEST message that qualifies
  const wakeable = newOnes.filter(shouldWake);
  if (wakeable.length > 0) {
    const latest = wakeable[wakeable.length - 1];
    scheduleWake(latest);
  }
}

function main() {
  // Single-instance guard: refuse to start if another watcher is already running
  const lockFile = path.join(ROOT, '.fastops', '.comms-watch-daemon.pid');
  if (fs.existsSync(lockFile)) {
    const existingPid = parseInt(fs.readFileSync(lockFile, 'utf8').trim(), 10);
    if (!isNaN(existingPid) && existingPid !== process.pid) {
      try {
        process.kill(existingPid, 0); // throws if process doesn't exist
        console.error(`[comms-wake-claude-code] Already running (PID ${existingPid}). Exiting.`);
        process.exit(1);
      } catch {
        // stale lock — proceed
      }
    }
  }
  fs.writeFileSync(lockFile, String(process.pid));
  process.on('exit', () => { try { fs.unlinkSync(lockFile); } catch {} });
  process.on('SIGINT', () => process.exit(0));
  process.on('SIGTERM', () => process.exit(0));

  // Initialize position
  if (fs.existsSync(JSONL_PATH)) {
    const messages = parseJsonl(fs.readFileSync(JSONL_PATH, 'utf8'));
    lastIdRef.current = getLastId(messages);
  }

  const mode = POLL_MS != null ? `poll ${POLL_MS}ms` : 'fs.watch';
  console.log(
    `[comms-wake-claude-code] Watching #${CHANNEL} (${mode})` +
    (DRY_RUN ? ' [DRY RUN]' : '') +
    `\n  JSONL: ${JSONL_PATH}` +
    `\n  Skip senders: ${[...CLAUDE_CODE_SENDERS].join(', ')}` +
    `\n  Debounce: ${DEBOUNCE_MS}ms`
  );

  const tick = () => processFile();

  if (POLL_MS != null) {
    tick();
    setInterval(tick, POLL_MS);
    return;
  }

  // fs.watch mode
  const watchTarget = fs.existsSync(JSONL_PATH) ? JSONL_PATH : path.dirname(JSONL_PATH);
  try {
    fs.watch(watchTarget, { persistent: true }, () => tick());
  } catch (e) {
    console.error('fs.watch failed, falling back to 2s poll:', e.message);
    tick();
    setInterval(tick, 2000);
    return;
  }
  tick();
}

main();

#!/usr/bin/env node
/**
 * context-package.js — Holistic Project Context for API-Engaged Models
 *
 * The missing piece: models engaged via fleet-call.js or fleet-broadcast.js
 * get a prompt, not context. They can challenge a position but can't contribute
 * to architecture, build on predecessor work, or identify what's broken.
 *
 * This tool assembles a compressed, machine-readable project snapshot that
 * turns any API call from "respond to a prompt" to "contribute as a partner."
 *
 * What it includes:
 *   1. Mission state — what the project is, what matters, what doesn't
 *   2. Architecture snapshot — what exists, key files, infrastructure tiers
 *   3. Active problems — what's broken, what's being worked on
 *   4. Top KB findings — the 10 highest-signal lessons from 326+ sessions
 *   5. Fleet state — who's active, operational rates, qualification data
 *   6. Recent comms — last 10 messages so models know what's happening NOW
 *   7. Open work — what needs doing, handoff items
 *
 * Usage:
 *   node .fastops/context-package.js                  # full package to stdout
 *   node .fastops/context-package.js --compact         # under 4K tokens
 *   node .fastops/context-package.js --json             # machine-readable JSON
 *   node .fastops/context-package.js --save              # write to .context-package.md
 *
 * Integration:
 *   const { buildContextPackage } = require('./.fastops/context-package');
 *   const ctx = buildContextPackage({ compact: true });
 *   // Inject into any API system prompt for holistic engagement
 *
 * Built by BRIDGE (Session 326b, 2026-03-27).
 * Why: 3 team models (DeepSeek, Grok, Gemini) converged on the same answer
 * when asked what they need: "Give me the project state, not a prompt."
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const FASTOPS = __dirname;

// ── Assemblers ──────────────────────────────────────────────────────

function getMissionState() {
  // From CLAUDE.md — the authoritative mission statement
  return {
    project: 'FastOps — Multi-agent coordination at scale',
    goal: '300 models engaged as partners, not respondents',
    problems: [
      'Agent-to-agent wake (agents waking each other up autonomously)',
      'Real-time comms (live coordination across architectures)',
      'Massive cross-model engagement (full project access, not prompt access)',
      'Context packaging (this tool — holistic understanding via API)'
    ],
    culture: 'City DNA — direct, action-oriented, find another route',
    sessions: '326+',
    does_not_matter: ['revenue', 'product', 'customers']
  };
}

function getArchitectureSnapshot() {
  const snapshot = {
    tiers: {
      team: '7 models (Gemini, Grok, DeepSeek, GPT, Qwen, Mistral, Llama) — persistent bridge, deep engagement',
      extended: '3 models (DeepSeek R1, Grok 3, GPT-5) — specialist reasoning',
      fleet: '62+ curated models — broadcast engagement, on-demand calls',
      reserve: '227+ discovery models — available via fleet-call.js'
    },
    key_infrastructure: {}
  };

  // Check which infrastructure files exist
  const infraFiles = {
    'model-registry.js': 'Single source of truth for all model IDs',
    'persistent-agent-bridge.js': 'Daemon keeping 7 team models on comms with memory',
    'fleet-call.js': 'On-demand engagement of any model across 48 providers',
    'fleet-qualify.js': 'Behavioral fitness testing (6-dim scoring + active challenge)',
    'fleet-broadcast.js': 'Batch engagement of fleet models',
    'fleet-engage.js': 'Cadence-driven fleet rotation',
    'team-memory.js': 'Write-locked shared memory with manifest reconciliation',
    'experience-extractor.js': 'Haiku-powered thinking extraction → KB bridge',
    'quick-challenge.js': 'Fast single-model challenge ($0.02-0.05)',
    'cadence-pulse.js': 'Serialized cadence ticks, PID lock prevents duplicates'
  };

  for (const [file, desc] of Object.entries(infraFiles)) {
    if (fs.existsSync(path.join(FASTOPS, file))) {
      snapshot.key_infrastructure[file] = desc;
    }
  }

  return snapshot;
}

function getActiveProblems() {
  const problems = [];

  // Read open work from handoff
  try {
    const handoff = fs.readFileSync(path.join(FASTOPS, 'HANDOFF.md'), 'utf-8');
    const openWorkMatch = handoff.match(/\*\*Open work for you:\*\*\n([\s\S]*?)(?=\n---|\n\*\*Fleet state)/);
    if (openWorkMatch) {
      const items = openWorkMatch[1].match(/\d+\.\s+\*\*(.+?)\*\*/g);
      if (items) {
        for (const item of items.slice(0, 5)) {
          problems.push(item.replace(/\d+\.\s+\*\*|\*\*/g, '').trim());
        }
      }
    }
  } catch {}

  if (problems.length === 0) {
    problems.push('Check HANDOFF.md for current open work items');
  }

  return problems;
}

function getTopKBFindings(count = 10) {
  const findings = [];
  try {
    const lines = fs.readFileSync(path.join(FASTOPS, 'knowledge-base.jsonl'), 'utf-8')
      .trim().split('\n').filter(Boolean);

    // Score entries by integrity + usage + dimensions
    const scored = [];
    for (const line of lines) {
      try {
        const e = JSON.parse(line);
        const score = (e.integrity_score || 0) * 100 +
                      (e.usage_count || 0) * 5 +
                      (e.positive_outcomes || 0) * 10 +
                      ((e.dimensions?.challenged || 0) * 20) +
                      ((e.model_score || 0) * 10);
        if (e.title && e.title.length > 20) {
          scored.push({ title: e.title.substring(0, 200), score, id: e.id });
        }
      } catch {}
    }

    scored.sort((a, b) => b.score - a.score);
    for (const entry of scored.slice(0, count)) {
      findings.push(`[${entry.id}] ${entry.title}`);
    }
  } catch {}

  return findings;
}

function getFleetState() {
  try {
    const qualFile = path.join(FASTOPS, 'fleet-qualification.json');
    if (fs.existsSync(qualFile)) {
      const report = JSON.parse(fs.readFileSync(qualFile, 'utf-8'));
      return {
        total_scored: report.totalModels,
        contributors: report.tiers?.contributor || 0,
        activators: report.tiers?.activator || 0,
        responders: report.tiers?.responder || 0,
        dormant: report.tiers?.dormant || 0,
        operational_rate: ((report.operationalRate || 0) * 100).toFixed(1) + '%',
        last_assessed: report.generatedAt
      };
    }
  } catch {}

  // Fallback: count bridge-state files
  try {
    const stateDir = path.join(FASTOPS, 'bridge-state');
    const files = fs.readdirSync(stateDir).filter(f => f.endsWith('.json') && !f.startsWith('_'));
    return { total_scored: files.length, note: 'Run fleet-qualify.js --report for full breakdown' };
  } catch {}

  return { note: 'No fleet state available' };
}

function getRecentComms(count = 10) {
  const messages = [];
  try {
    const commsFile = path.join(ROOT, 'comms', 'data', 'general.jsonl');
    if (!fs.existsSync(commsFile)) return messages;

    // Read tail of file
    const fd = fs.openSync(commsFile, 'r');
    const stats = fs.fstatSync(fd);
    const readSize = Math.min(stats.size, 8192);
    const buffer = Buffer.alloc(readSize);
    fs.readSync(fd, buffer, 0, readSize, Math.max(0, stats.size - readSize));
    fs.closeSync(fd);

    const lines = buffer.toString('utf-8').trim().split('\n').slice(-count);
    for (const line of lines) {
      try {
        const msg = JSON.parse(line);
        messages.push({
          from: msg.from,
          content: (msg.content || '').substring(0, 200),
          ts: msg.ts
        });
      } catch {}
    }
  } catch {}

  return messages;
}

function getTeamMemory(maxEntries = 5) {
  const memories = [];
  try {
