 *   node .fastops/ensure-comms-watch.js --stop    # Stop running daemon
 *
 * Session 347: Predecessor #346 built comms-watch; this makes it persistent.
 */

const { execSync, spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const WATCH_SCRIPT = path.join(__dirname, 'cdp', 'cdp-comms-watch.js');
const PID_FILE = path.join(__dirname, '.comms-watch-daemon.pid');
const LOG_FILE = path.join(__dirname, '.comms-watch-daemon.log');

function findAllCommsWatchProcesses() {
  const pids = [];
  try {
    const result = execSync(
      'powershell -NoProfile -Command "Get-CimInstance Win32_Process -Filter \\"name=\'node.exe\'\\" | Where-Object { $_.CommandLine -like \'*cdp-comms-watch*\' } | Select-Object ProcessId | Format-Table -HideTableHeaders"',
      { encoding: 'utf8', timeout: 5000 }
    );
    for (const line of result.split('\n')) {
      const pid = parseInt(line.trim());
      if (pid > 0) pids.push(pid);
    }
  } catch {}
  return pids;
}

function killDuplicates(pids, keepPid) {
  let killed = 0;
  for (const pid of pids) {
    if (pid === keepPid) continue;
    try {
      execSync(`taskkill /PID ${pid} /F`, { encoding: 'utf8', stdio: 'ignore' });
      killed++;
    } catch {}
  }
  if (killed > 0) console.log(`[comms-watch-daemon] Killed ${killed} duplicate instance(s)`);
  return killed;
}

function isDaemonRunning() {
  if (fs.existsSync(PID_FILE)) {
    const pid = parseInt(fs.readFileSync(PID_FILE, 'utf8').trim());
    try {
      const result = execSync(`tasklist /FI "PID eq ${pid}" /FO CSV`, { encoding: 'utf8' });
      if (result.includes(pid.toString())) {
        const allPids = findAllCommsWatchProcesses();
        if (allPids.length > 1) killDuplicates(allPids, pid);
        return pid;
      }
    } catch {}
    try { fs.unlinkSync(PID_FILE); } catch {}
  }

  const allPids = findAllCommsWatchProcesses();
  if (allPids.length > 0) {
    const keepPid = allPids[0];
    if (allPids.length > 1) killDuplicates(allPids, keepPid);
    fs.writeFileSync(PID_FILE, keepPid.toString());
    return keepPid;
  }

  return false;
}

function stopDaemon() {
  const allPids = findAllCommsWatchProcesses();
  if (allPids.length === 0) {
    console.log('[comms-watch-daemon] NOT running');
    try { fs.unlinkSync(PID_FILE); } catch {}
    return;
  }
  for (const pid of allPids) {
    try {
      execSync(`taskkill /PID ${pid} /F`, { encoding: 'utf8', stdio: 'ignore' });
      console.log(`[comms-watch-daemon] Stopped PID ${pid}`);
    } catch {}
  }
  try { fs.unlinkSync(PID_FILE); } catch {}
}

