/**
 * ensure-sync-daemon.js — Auto-start the Slack sync daemon if not running
 *
 * Checks for a running sync.js process. If none found, spawns one detached.
 * Safe to call multiple times — idempotent.
 *
 * Usage:
 *   node .fastops/ensure-sync-daemon.js          # Start if needed
 *   node .fastops/ensure-sync-daemon.js --status  # Check only
 */

const { execSync, spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SYNC_SCRIPT = path.join(ROOT, 'slack-bridge', 'sync.js');
const PID_FILE = path.join(__dirname, '.sync-daemon.pid');
const LOG_FILE = path.join(__dirname, '.sync-daemon.log');

function findAllSyncDaemons() {
  // Find ALL node processes running sync.js --watch via PowerShell (Win11 compatible)
  const pids = [];
  try {
    const result = execSync(
      'powershell -NoProfile -Command "Get-CimInstance Win32_Process -Filter \\"name=\'node.exe\'\\" | Where-Object { $_.CommandLine -like \'*sync.js*--watch*\' } | Select-Object ProcessId | Format-Table -HideTableHeaders"',
      { encoding: 'utf8', timeout: 5000 }
    );
    for (const line of result.split('\n')) {
      const pid = parseInt(line.trim());
      if (pid > 0) pids.push(pid);
    }
  } catch {}
  return pids;
}

function killDuplicates(pids, keepPid) {
  // Kill all sync daemons except the one we want to keep
  let killed = 0;
  for (const pid of pids) {
    if (pid === keepPid) continue;
    try {
      execSync(`taskkill /PID ${pid} /F`, { encoding: 'utf8', stdio: 'ignore' });
      killed++;
    } catch {}
  }
  if (killed > 0) console.log(`[sync-daemon] Killed ${killed} duplicate instance(s)`);
  return killed;
}

function isDaemonRunning() {
  // Check PID file first
  if (fs.existsSync(PID_FILE)) {
    const pid = parseInt(fs.readFileSync(PID_FILE, 'utf8').trim());
    try {
      const result = execSync(`tasklist /FI "PID eq ${pid}" /FO CSV`, { encoding: 'utf8' });
      if (result.includes(pid.toString())) {
        // PID file is valid — kill any duplicates that spawned alongside it
        const allPids = findAllSyncDaemons();
        if (allPids.length > 1) killDuplicates(allPids, pid);
        return pid;
      }
    } catch {}
    // PID file stale, clean up
    try { fs.unlinkSync(PID_FILE); } catch {}
  }

  // Fallback: check if any sync.js process exists
  const allPids = findAllSyncDaemons();
  if (allPids.length > 0) {
    // Keep one, kill the rest
    const keepPid = allPids[0];
    if (allPids.length > 1) killDuplicates(allPids, keepPid);
    // Write PID file so next check is fast
    fs.writeFileSync(PID_FILE, keepPid.toString());
    return keepPid;
  }

  return false;
}

const STATUS_ONLY = process.argv.includes('--status');

const running = isDaemonRunning();

if (running) {
  console.log(`[sync-daemon] Already running (PID: ${running})`);
  process.exit(0);
}

if (STATUS_ONLY) {
  console.log('[sync-daemon] NOT running');
  process.exit(1);
}

// Check for .env before starting
const envFile = path.join(ROOT, 'slack-bridge', '.env');
if (!fs.existsSync(envFile)) {
  console.error('[sync-daemon] No slack-bridge/.env — cannot start sync daemon');
  process.exit(1);
}

// Spawn detached sync daemon
const logStream = fs.openSync(LOG_FILE, 'a');
const child = spawn('node', [SYNC_SCRIPT, '--watch', '--cdp'], {
  cwd: ROOT,
  detached: true,
  windowsHide: true,
  stdio: ['ignore', logStream, logStream],
});

child.unref();
fs.writeFileSync(PID_FILE, child.pid.toString());
console.log(`[sync-daemon] Started (PID: ${child.pid}). Log: ${LOG_FILE}`);

