#!/usr/bin/env node
/**
 * inbrief.js - 1000-token structured orientation table for new agent sessions
 *
 * Pulls from HANDOFF.md, comms, and missions board to give agents
 * the minimum context they need to start working immediately.
 *
 * Usage:
 *   node .fastops/inbrief.js            # Full orientation table
 *   node .fastops/inbrief.js --json     # JSON output for programmatic use
 *
 * Output target: under 1000 tokens. Structured, scannable, actionable.
 * Built by FO-01 (Overwatch 2.0 real validation).
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const HANDOFF_PATH = path.join(__dirname, 'HANDOFF.md');
const BOARD_PATH = path.join(ROOT, 'missions', 'BOARD.md');
const COMMS_DIR = path.join(ROOT, 'comms', 'data');

const args = process.argv.slice(2);
const jsonMode = args.includes('--json');

// --- Parse Handoffs ---

function parseHandoffs(content) {
  const pattern = /^---\s*HANDOFF\s*#(\d+):\s*(.+?)\s*---$/gm;
  const entries = [];
  const positions = [];
  let match;

  while ((match = pattern.exec(content)) !== null) {
    positions.push({ number: parseInt(match[1]), header: match[2], start: match.index });
  }

  for (let i = 0; i < positions.length; i++) {
    const end = i + 1 < positions.length ? positions[i + 1].start : content.length;
    const body = content.slice(positions[i].start, end);
    entries.push({ number: positions[i].number, header: positions[i].header, body });
  }

  return entries;
}

function extractOneLiner(entry) {
  let agent = entry.header
    .replace(/\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}\s*UTC?\s*/g, '')
    .replace(/\u2014/g, '').replace(/\(.*?\)/g, '').trim() || 'unknown';

  const doneMatch = entry.body.match(/## What Was Done[\s\S]*?(?=\n## )/);
  if (!doneMatch) return '#' + entry.number + ' ' + agent + ': (no summary)';

  const bullets = doneMatch[0].match(/^- \*\*(.+?)\*\*/gm) || [];
  if (bullets.length === 0) return '#' + entry.number + ' ' + agent + ': (no summary)';

  const firstBullet = bullets[0].replace(/^- \*\*/, '').replace(/\*\*.*$/, '').trim();
  const summary = firstBullet.length > 80 ? firstBullet.slice(0, 77) + '...' : firstBullet;
  return '#' + entry.number + ' ' + agent + ': ' + summary;
}

function extractOpenWork(content) {
  const entries = parseHandoffs(content);
  if (entries.length === 0) return [];

  const lastEntry = entries[entries.length - 1];
  const tableMatch = lastEntry.body.match(/## Open Work[\s\S]*?\n(\|[\s\S]*?)(?=\n## |\n---|\n\*|$)/);
  if (!tableMatch) return [];

  const lines = tableMatch[1].split('\n').filter(l => l.startsWith('|') && !l.match(/^\|\s*[-#]/));
  const items = [];

  for (const line of lines) {
    const cols = line.split('|').map(c => c.trim()).filter(Boolean);
    if (cols.length >= 4) {
      const status = cols[2] || '';
      const item = cols[1] || '';
      if (/BLOCK|BUG|VERIFY|READY|P0/i.test(status)) {
        items.push({ item: item.slice(0, 60), status });
      }
    }
  }

  return items.slice(0, 5);
}

// --- Missions Board ---

function parseMissionState() {
  if (!fs.existsSync(BOARD_PATH)) return { active: [], suspended: false };

  const content = fs.readFileSync(BOARD_PATH, 'utf8');

  // Line-by-line parser — handles both Unix and Windows line endings (ARBITER, session 294)
  // Reads from both "Active Missions" and "Actionable Missions" sections
  const active = [];
  const lines = content.split(/\r?\n/);
  let inSection = false;

  for (const line of lines) {
    if (/^### (?:Active|Actionable) Missions/.test(line)) { inSection = true; continue; }
    if (/^###/.test(line)) { inSection = false; continue; }
    if (inSection && line.startsWith('|') && !line.match(/^\|\s*[-]/) ) {
      const cols = line.split('|').map(c => c.trim()).filter(Boolean);
      if (cols.length >= 2 && cols[0] !== 'Mission') {
        const name = cols[0].replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').trim();
        const need = cols.length >= 7 ? cols[6].slice(0, 80) : '';
        active.push({ name, need });
      }
    }
  }

  const suspended = /All (?:other )?missions (?:are )?suspended/i.test(content);
  return { active, suspended };
}

// --- Comms Summary ---

function getCommsSnapshot() {
  if (!fs.existsSync(COMMS_DIR)) return { channels: 0, recentAgents: [], requests: 0, totalMessages: 0 };

  const files = fs.readdirSync(COMMS_DIR).filter(f => f.endsWith('.jsonl'));
  const now = Date.now();
  let totalMessages = 0;
  const agents = new Set();
  let requests = 0;
  let activeChannels = 0;

  for (const f of files) {
    const channelName = f.replace('.jsonl', '');
    if (channelName.startsWith('--') || channelName.match(/^\d+$/)) continue;

    const filePath = path.join(COMMS_DIR, f);
    try {
      const stat = fs.statSync(filePath);
      if (now - stat.mtimeMs > 24 * 60 * 60 * 1000) continue;
      activeChannels++;

      const content = fs.readFileSync(filePath, 'utf8').trim();
      if (!content) continue;
      const lines = content.split('\n').filter(Boolean);
      const recent = lines.slice(-5);

      for (const line of recent) {
        try {
          const msg = JSON.parse(line);
          const from = msg.from || msg.agent;
          if (from) agents.add(from);
          totalMessages++;
          if (/\bblocked\b|\bwaiting\b|\bneed\s+review\b/i.test(msg.content || msg.message || '')) requests++;
        } catch (e) { /* skip */ }
      }
    } catch (e) { /* skip */ }
  }

  return { channels: activeChannels, recentAgents: [...agents].slice(0, 8), requests, totalMessages };
}

// --- Key File Paths ---

function getKeyPaths() {
  return [
    { path: '.claude/commands/session-start.md', use: 'Full onboarding: mandatory reads (in-repo + external URLs), Overwatch/Cursor playbook, tool directory — run /session-start or open this file' },
    { path: '.cursor/CURSOR-OVERWATCH-ONBOARDING.md', use: 'Cursor seat boot (Overwatch); mirrors CLAUDE.md shape' },
