    { path: 'STRATEGY.md', use: 'How agents work (CDP, sign-off, tools)' },
    { path: 'comms/source.js --all-channels', use: 'Live comms summary' },
    { path: '.fastops/kb-query.js "topic"', use: 'Predecessor knowledge' },
  ];
}

// --- Build Output ---

function buildInbrief() {
  const handoffContent = fs.existsSync(HANDOFF_PATH)
    ? fs.readFileSync(HANDOFF_PATH, 'utf8')
    : '';

  const entries = parseHandoffs(handoffContent);
