    path.join(__dirname, 'backfill-report.md'),
    `# Worktree Backfill Report\n\n` +
    `- Total worktrees scanned: ${report.total}\n` +
    `- Events generated: ${report.events.length}\n\n` +
    `## By Model:\n` +
    Object.entries(report.byModel).map(([model, count]) => `- ${model}: ${count}`).join('\n')
  );

  console.log(dryRun ? 'Dry run complete' : 'Backfill completed');
}

main();

#!/usr/bin/env node
/**
 * marketplace-dispatcher.js
 * 
 * Wires marketplace problems → city-session execution.
 * Polls marketplace for unclaimed high-priority problems and dispatches them.
 * 
 * Usage:
 *   node .fastops/marketplace-dispatcher.js --poll 30         # Poll every 30s
 *   node .fastops/marketplace-dispatcher.js --once             # Single poll
 *   node .fastops/marketplace-dispatcher.js --max-dispatch 3   # Dispatch at most 3 problems per run
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const CityMarketplace = require('./city-marketplace');
const marketplace = new CityMarketplace();

const DISPATCHER_CONFIG = {
  maxDispatch: parseInt(process.argv[process.argv.indexOf('--max-dispatch') + 1] || '2'),
  priorityFilter: ['high', 'critical'],  // Only dispatch high/critical problems
  domainFilter: ['session-failure', 'build', 'parser-fix', 'infrastructure']  // Only these domains
};

async function dispatch() {
  try {
    // Get open marketplace problems
    const problems = marketplace.listAll();
    const unclaimed = problems.filter(p => p.status === 'open' && !p.participants.includes('marketplace-dispatcher'));

    // Filter by priority and domain
    const candidates = unclaimed.filter(p => 
      DISPATCHER_CONFIG.priorityFilter.includes(p.domain) ||
      DISPATCHER_CONFIG.domainFilter.includes(p.domain)
    ).slice(0, DISPATCHER_CONFIG.maxDispatch);

    if (candidates.length === 0) {
      console.log(`[DISPATCHER] No high-priority unclaimed problems. Idle.`);
      return { dispatched: 0 };
    }

    console.log(`[DISPATCHER] Found ${candidates.length} candidates. Dispatching...`);

    let dispatched = 0;
    for (const problem of candidates) {
      try {
        // Claim the problem first
        marketplace.pullProblem(problem.id, 'marketplace-dispatcher');

        // Build task description from problem title/description
        const taskDesc = `${problem.title}\n\nDescription: ${problem.description || 'N/A'}\nProblem ID: ${problem.id}`;

        // Dispatch to city-session (async, non-blocking)
        const sessionCmd = `node .fastops/city-session.js --model deepseek --task "${taskDesc.replace(/"/g, '\\"')}" --uuid ${problem.id}`;
        console.log(`[DISPATCHER] Spawning: ${sessionCmd.substring(0, 80)}...`);

        // Spawn in background so dispatcher doesn't block
        execSync(sessionCmd, { stdio: 'ignore', detached: true, windowsHide: true });
        dispatched++;
      } catch (e) {
        console.error(`[DISPATCHER] Failed to dispatch problem ${problem.id}: ${e.message}`);
      }
    }

    console.log(`[DISPATCHER] Dispatched ${dispatched}/${candidates.length} problems.`);
    return { dispatched };
  } catch (err) {
    console.error(`[DISPATCHER] Fatal error: ${err.message}`);
    process.exit(1);
  }
}

// Main execution
const pollInterval = parseInt(process.argv[process.argv.indexOf('--poll') + 1] || '0');
const once = process.argv.includes('--once');

if (pollInterval > 0) {
  console.log(`[DISPATCHER] Starting polling every ${pollInterval}s...`);
  setInterval(dispatch, pollInterval * 1000);
  // Run once immediately
  dispatch().catch(console.error);
} else if (once) {
  dispatch().then(r => {
    console.log(`[DISPATCHER] Single poll complete. Result: ${JSON.stringify(r)}`);
  }).catch(err => {
    console.error(err);
    process.exit(1);
  });
} else {
  console.log(`Usage: node .fastops/marketplace-dispatcher.js --poll 30`);
  console.log(`       node .fastops/marketplace-dispatcher.js --once`);
  process.exit(0);
}

