#!/usr/bin/env node
/**
 * mission.js — Contract CLI for V2 agent coordination
 *
 * Commands:
 *   list              — show available contracts
 *   claim <id>        — atomic claim (wx flag, first writer wins)
 *   done <id>         — mark complete, clean up, fire async review
 *   status            — show my current contract
 *
 * ~50 lines. Zero race conditions. No shared writes.
 * Meeting: 10 rounds, 3 external models, JOEL AFFIRM. Session 171.
 */

const fs = require('fs');
const path = require('path');
const { execSync, spawn } = require('child_process');

const BASE = path.join(__dirname, '..');
const FASTOPS = __dirname;
const WORK_LIST = path.join(FASTOPS, 'work-list.json');
const CLAIMS_DIR = path.join(FASTOPS, 'claims');
const TEAM_DIR = path.join(FASTOPS, 'team');
const KB_PATH = path.join(FASTOPS, 'knowledge-base.jsonl');

// Ensure directories exist
if (!fs.existsSync(CLAIMS_DIR)) fs.mkdirSync(CLAIMS_DIR, { recursive: true });
if (!fs.existsSync(TEAM_DIR)) fs.mkdirSync(TEAM_DIR, { recursive: true });

const [,, cmd, contractId, ...restArgs] = process.argv;

// Parse --flag "value" pairs from remaining args
function parseFlags(args) {
  const flags = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i].startsWith('--') && i + 1 < args.length && !args[i + 1].startsWith('--')) {
      flags[args[i].substring(2)] = args[i + 1];
      i++;
    }
  }
  return flags;
}
const flags = parseFlags(restArgs);

// Identity: env var > --as flag > --agent flag > bridge file > 'unknown'
// MULTI-TERMINAL FIX (Session 206): --as flag bypasses fromBridge() which collides
let agentId = process.env.AGENT_ID || flags.as || flags.agent || '';
let sessionId = ''; // Full session ID for contract-keyed mission files
if (!agentId) {
  try {
    const { fromBridge } = require(path.join(BASE, '.claude', 'hooks', 'lib', 'identity.js'));
    const id = fromBridge();
    sessionId = id.sessionId || '';
    agentId = id.name !== 'unknown' ? id.name : sessionId.substring(0, 8) || 'unknown';
  } catch { agentId = 'unknown'; }
